export { anatomy, type PaginationPart, parts } from "./pagination.anatomy";
export { connect } from "./pagination.connect";
export {
  getControlEls,
  getEllipsisId,
  getItemId,
  getNextTriggerId,
  getPrevTriggerId,
  getRootEl,
  getRootId,
  ownsFocus,
} from "./pagination.dom";
export { machine } from "./pagination.machine";
export type {
  PaginationApi,
  PaginationEllipsisProps,
  PaginationItemKind,
  PaginationItemProps,
  PaginationMachineProps,
  PaginationPageChangeDetails,
  PaginationPageItem,
  PaginationPageRange,
  PaginationPageSizeChangeDetails,
  PaginationSchema,
  PaginationTranslations,
  ResolvedPaginationMachineProps,
} from "./pagination.types";

import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

/**
 * Five parts and deliberately no `list`: the root is a named `navigation`
 * landmark and every item carries its own "page N" label, so `ul`/`li` add
 * nothing the accessibility tree needs. A consumer who wants list semantics
 * composes their own markup through `render` — recorded as divergence n°3 of
 * the spec, not an oversight.
 */
export type PaginationPart = "root" | "item" | "ellipsis" | "prevTrigger" | "nextTrigger";

export const anatomy: Anatomy<PaginationPart> = createAnatomy("pagination").parts(
  "root",
  "item",
  "ellipsis",
  "prevTrigger",
  "nextTrigger",
);

export const parts: Record<PaginationPart, AnatomyPart> = anatomy.build();

/**
 * Pure, DOM-free, replayable on a server.
 *
 * Every control is tabbable — no roving tabindex, which diverges from the other
 * composites on purpose: a pagination is a `navigation` landmark made of
 * links/buttons (the Breadcrumb precedent), so each control stays individually
 * reachable and the arrows are an *enrichment* of Tab, not a replacement.
 *
 * **The declared keyboard divergences, in full**, because "enrichment" is only
 * honest when the bill is written out. Claimed: the on-axis arrows (they move
 * the focus along the bar; off-axis they stay the browser's and scroll) and
 * PageUp/PageDown (they step the page, which is the same thing the gamepad's
 * LT/RT mean — CDC §4.4). Given back: **Home and End**. Those two are free in a
 * single-tab-stop composite, where an end is otherwise reached arrow by arrow;
 * they are not free here, where Tab reaches both ends in a press or two and the
 * browser binds them to the top and the bottom of the document.
 *
 * Activation is the native click: the controls are real `<button>`/`<a>`
 * elements, so Enter and Space are the browser's own, and the keydown handler
 * only mirrors them into the pressed *visual* — the six-line reasoning of
 * `button.connect`. The `if (event.defaultPrevented) return;` at the head of
 * every handler is also the anti-double-step gate: an input system's keymap
 * turns PageUp/PageDown into intents and prevents the native event, so the
 * connect sees `defaultPrevented` and does not replay the step.
 */

import { ariaAttr, dataAttr } from "../../dom/attrs";
import { resolveDir } from "../../dom/text-dir";
import { getRovingKeyAction } from "../../focus/roving-focus";
import type {
  ButtonProps,
  EventHandler,
  HTMLProps,
  NormalizeProps,
  PropTypes,
} from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { parts } from "./pagination.anatomy";
import {
  getEllipsisId,
  getItemId,
  getNextTriggerId,
  getPrevTriggerId,
  getRootEl,
  getRootId,
} from "./pagination.dom";
import type {
  PaginationApi,
  PaginationEllipsisProps,
  PaginationItemProps,
  PaginationSchema,
} from "./pagination.types";

type PaginationEvent = PaginationSchema["event"];

/**
 * The two keys a real `<button>` or `<a>` turns into a click. A pair, so it is a
 * comparison rather than the `ReadonlySet` `button.connect` uses over the same
 * two members: a set of two buys no lookup a `===` does not already give.
 */
function isActivationKey(key: string): boolean {
  return key === "Enter" || key === " ";
}

/** `HTMLProps` has no anchor slot; link mode needs exactly one attribute more. */
type AnchorProps = HTMLProps & { readonly href?: string | undefined };

export function connect<T extends PropTypes>(
  service: Service<PaginationSchema>,
  normalize: NormalizeProps<T>,
): PaginationApi<T> {
  const { context, computed, prop, send, scope } = service;

  const totalPages = computed("totalPages");
  const page = computed("page");
  const pageSize = context.get("pageSize");
  const canPrev = computed("canPrev");
  const canNext = computed("canNext");
  const disabled = prop("disabled");
  const translations = prop("translations");
  const isLink = prop("type") === "link";
  const getPageUrl = prop("getPageUrl");

  const focusedValue = context.get("focusedValue");
  // Read once, when the focus landed, and held: the modality of *now* flips to
  // pointer after 300 ms of mouse movement whether or not the focus moved, and
  // a ring that blinks out under the user's hands was the result.
  const focusSource = context.get("focusSource");
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);
  const pressedValue = context.get("pressedValue");

  /**
   * Up, leave and cancel all mean the same thing — the press is over — so they
   * are one function referenced three times rather than the same three lines
   * written out three times, and it is built once for the whole nav instead of
   * once per control.
   */
  const endPress: EventHandler<PointerEvent> = (event) => {
    if (event.defaultPrevented) return;
    send({ type: "ROOT.PRESS_END" });
  };

  /**
   * The head guard of both keyboard handlers, and it doubles as the
   * anti-double-step gate — see the module comment: a running input system has
   * already turned PageUp/PageDown into a consumed intent and prevented the
   * native event. Shift is deliberately *not* in here: keydown refuses it, keyup
   * must not, or a Space pressed bare and released under Shift leaves the
   * pressed visual stuck on.
   */
  const isChorded = (event: KeyboardEvent): boolean =>
    event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey;

  /**
   * Everything a control wears that is not its own identity: the state
   * attributes, the focus and press mirrors, the keyboard. One function for the
   * item and both triggers, and one spread per control — the state and the
   * handlers were two functions taking the same two arguments and called at the
   * same three sites, which is one function written twice.
   */
  const control = (value: string, refused: boolean): HTMLProps => {
    const focused = focusedValue === value;
    return {
      "data-disabled": dataAttr(refused),
      "data-pressed": dataAttr(pressedValue === value),
      "data-focus-visible": dataAttr(focused && focusVisible),
      // On the focused control only: the composite has one focus, and an
      // attribute claiming otherwise on every cell describes nothing.
      "data-focus-source": focused ? (focusSource ?? undefined) : undefined,

      onFocus(event) {
        if (event.defaultPrevented) return;
        send({ type: "ROOT.FOCUS", value });
      },
      onBlur(event) {
        if (event.defaultPrevented) return;
        send({ type: "ROOT.BLUR" });
      },
      onPointerDown(event) {
        if (event.defaultPrevented || refused) return;
        send({ type: "ROOT.PRESS_START", value });
      },
      onPointerUp: endPress,
      onPointerLeave: endPress,
      onPointerCancel: endPress,
      onKeyDown(event) {
        if (isChorded(event) || event.shiftKey) return;

        if (event.key === "PageUp") {
          event.preventDefault();
          send({ type: "PAGE.PREV" });
          return;
        }
        if (event.key === "PageDown") {
          event.preventDefault();
          send({ type: "PAGE.NEXT" });
          return;
        }

        // Enter and Space are never prevented: on a real button or anchor the
        // browser turns them into the click that actually activates. Only the
        // pressed visual is mirrored, and a held key is one press.
        if (isActivationKey(event.key)) {
          if (!refused && !event.repeat) send({ type: "ROOT.PRESS_START", value });
          return;
        }

        // The RTL mirror lives in `getRovingKeyAction`, once. `bothAxes: false`:
        // off-axis the arrow stays the browser's and scrolls the page.
        const action = getRovingKeyAction(event.key, {
          orientation: "horizontal",
          dir: resolveDir(prop("dir"), getRootEl(scope)),
          bothAxes: false,
        });
        // `first` and `last` are Home and End, and they are given back to the
        // page — the one place this bar parts company with the composites
        // `getRovingKeyAction` was written for. There the two keys are free,
        // because a composite is a *single* tab stop and an end is otherwise
        // reached arrow by arrow. Here every control is tabbable (see the module
        // comment), Tab reaches both ends in a press or two, and the browser binds
        // Home/End to the top and the bottom of the document. An enrichment may
        // not cost more than it adds. Filtered on the action rather than on the
        // key so there is one decision point, not two.
        if (action === null || action === "first" || action === "last") return;
        event.preventDefault();
        send({ type: "ROOT.NAVIGATE", action });
      },
      onKeyUp(event) {
        if (isChorded(event)) return;
        if (isActivationKey(event.key)) send({ type: "ROOT.PRESS_END" });
      },
    };
  };

  /**
   * One dialect call for two elements: the api slot stays `button` while link
   * mode renders an anchor (`normalize.element`) — the contract §3 declares.
   */
  const renderControl = (shared: ButtonProps, href: string | undefined): T["button"] =>
    isLink
      ? // Through `unknown` on purpose: every slot of a concrete `PropTypes` is the
        // same type, but `T["element"]` and `T["button"]` are two unrelated indexed
        // accesses while `T` is still a parameter, and neither is comparable to the
        // other. The api's slot is `button` because that is the contract §3 states;
        // the element under it is the adapter's business.
        (normalize.element({ ...shared, href } as AnchorProps) as unknown as T["button"])
      : normalize.button({ ...shared, type: "button" });

  /**
   * The three controls activate the same way, so the shape is written once: the
   * consumer's veto first, then the refusal — which in link mode must also stop
   * the browser following an href the control is refusing to honour — then the
   * event. Only the event differs, and it is the argument.
   */
  const activate =
    (refused: boolean, event: PaginationEvent): EventHandler<MouseEvent> =>
    (click) => {
      if (click.defaultPrevented) return;
      if (refused) {
        // A dead link must not navigate the page.
        if (isLink) click.preventDefault();
        return;
      }
      send(event);
    };

  return {
    page,
    pageSize,
    totalPages,
    pages: computed("pages"),
    pageRange: computed("pageRange"),
    isFirstPage: page === 1,
    isLastPage: page === totalPages,

    setPage(next: number): void {
      send({ type: "PAGE.SET", page: next });
    },

    setPageSize(size: number): void {
      send({ type: "PAGESIZE.SET", size });
    },

    nextPage(): void {
      send({ type: "PAGE.NEXT" });
    },

    prevPage(): void {
      send({ type: "PAGE.PREV" });
    },

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        id: getRootId(scope),
        dir: prop("dir"),
        "aria-label": translations?.rootLabel ?? "pagination",
        "data-disabled": dataAttr(disabled),
        // The landmark is also the spatial zone: the engine's default entry
        // strategy (`last`) brings a d-pad back to the control it left.
        "data-snav": "container",
      }),

    getItemProps: ({ page: item }: PaginationItemProps): T["button"] => {
      const value = String(item);
      const current = item === page;

      const shared: ButtonProps = {
        ...parts.item.attrs,
        id: getItemId(scope, item),
        "aria-label": translations?.itemLabel?.({ page: item, totalPages }) ?? `page ${item}`,
        // The href stays on the current page in link mode (a link to itself);
        // `aria-current` is what carries the state.
        "aria-current": current ? "page" : undefined,
        "data-value": value,
        "data-current": dataAttr(current),
        ...control(value, disabled),
        onClick: activate(disabled, { type: "ITEM.CLICK", page: item }),
      };
      return renderControl(shared, getPageUrl?.({ page: item }));
    },

    getEllipsisProps: (ellipsisProps: PaginationEllipsisProps): T["element"] =>
      normalize.element({
        ...parts.ellipsis.attrs,
        id: getEllipsisId(scope, ellipsisProps.index),
        // Purely presentational, never focusable; the content is the
        // consumer's (an inline SVG, never a text glyph).
        "aria-hidden": ariaAttr(true),
        "data-index": String(ellipsisProps.index),
      }),

    getPrevTriggerProps: (): T["button"] => {
      // `canPrev` is already `!disabled && page > 1` — the machine folds the
      // disabled state into both computeds, so re-testing it here said the same
      // thing twice.
      const refused = !canPrev;
      const shared: ButtonProps = {
        ...parts.prevTrigger.attrs,
        id: getPrevTriggerId(scope),
        "aria-label": translations?.prevTriggerLabel ?? "previous page",
        // Never the native `disabled`: at the last activation before the bound
        // the button would disable itself under the focus and drop it on
        // `body`. `aria-disabled` keeps the control focusable — the default
        // here, not an opt-in (§2).
        "aria-disabled": ariaAttr(refused),
        ...control("prev", refused),
        onClick: activate(refused, { type: "PREV.CLICK" }),
      };
      return renderControl(shared, getPageUrl?.({ page: Math.max(1, page - 1) }));
    },

    getNextTriggerProps: (): T["button"] => {
      const refused = !canNext;
      const shared: ButtonProps = {
        ...parts.nextTrigger.attrs,
        id: getNextTriggerId(scope),
        "aria-label": translations?.nextTriggerLabel ?? "next page",
        "aria-disabled": ariaAttr(refused),
        ...control("next", refused),
        onClick: activate(refused, { type: "NEXT.CLICK" }),
      };
      return renderControl(shared, getPageUrl?.({ page: Math.min(totalPages, page + 1) }));
    },
  };
}

import { contains, queryAll } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "pagination";

/**
 * Written out rather than read from `parts`: the anatomy builds the same
 * strings, and a component that imports its own anatomy into its DOM helpers
 * pays for the builder in every bundle that only wanted a query — the `tabs`
 * decision, kept.
 */
const ROOT_SELECTOR = '[data-part~="pagination:root"]';
const CONTROL_SELECTOR =
  '[data-part~="pagination:item"], [data-part~="pagination:prev-trigger"], [data-part~="pagination:next-trigger"]';

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getItemId(scope: Scope, page: number): string {
  return getPartId(scope, COMPONENT, "item", String(page));
}

export function getEllipsisId(scope: Scope, index: number): string {
  return getPartId(scope, COMPONENT, "ellipsis", String(index));
}

export function getPrevTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "prev-trigger");
}

export function getNextTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "next-trigger");
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

/**
 * The focusable controls of the nav in DOM order — the items and the two
 * triggers, ellipses excluded because they are never focusable. Read when it is
 * needed rather than kept in a registry, and filtered to *this* root so a
 * pagination nested in another component's pagination (a table per page of an
 * outer list is an ordinary shape) never hands its controls to the wrong
 * machine.
 */
export function getControlEls(scope: Scope): HTMLElement[] {
  const root = getRootEl(scope);
  if (root === null) return [];
  return queryAll<HTMLElement>(root, CONTROL_SELECTOR).filter(
    (control) => control.closest(ROOT_SELECTOR) === root,
  );
}

/**
 * Whether the focus is inside *this* pagination — the gate LT/RT are consumed
 * behind. Same contract as `tabs.ownsFocus`: the nearest `pagination:root`
 * ancestor decides, and `contains` covers the shadow boundary `closest` stops
 * at.
 */
export function ownsFocus(scope: Scope): boolean {
  const root = getRootEl(scope);
  const active = scope.getActiveElement();
  if (root === null || active === null) return false;
  const owner = active.closest(ROOT_SELECTOR);
  return owner === null ? contains(root, active) : owner === root;
}

/**
 * A pagination has no lifecycle — one state, everything on the root `on:`, the
 * same shape as `toggle-group` and `tabs`. Three decisions are worth stating.
 *
 * **The clamped page is a computed, never a write.** A controlled consumer may
 * hold `page` out of bounds; `computed.page` is what every reader sees, and the
 * watch below only *asks* for the correction (`onPageChange`) the way
 * `tabs.syncTriggers` re-settles a dangling value.
 *
 * **The focus never moves on a page step.** Whoever clicked `nextTrigger` is
 * already on it, and whoever pulled RT from an item keeps their focus where it
 * is — the `tabs.stepValue` doctrine, simpler here because there is no follow.
 *
 * **LT/RT, not LB/RB.** The shoulder pair is `tabNext`/`tabPrev` and `tabs`
 * already captures it from anywhere in its root; a pagination inside a tab
 * panel that took the same pair would steal the tab change. The triggers that
 * are literally named `pageUp`/`pageDown` are the ones consumed here, and only
 * while the focus is inside the nav (`ownsFocus`) — outside it, PageUp/PageDown
 * keep their first meaning, scrolling the page.
 */

import { getNextIndex } from "../../focus/roving-focus";
import { createMachine } from "../../machine/create-machine";
import type { Machine, MachineParams } from "../../machine/types";
import { focusElement, getInputModality, trackInputModality } from "../../nav";
import type { InputModality } from "../../types";
import { getControlEls, getRootEl, ownsFocus } from "./pagination.dom";
import type { PaginationPageItem, PaginationSchema } from "./pagination.types";

type Params = MachineParams<PaginationSchema>;

function pageRange(from: number, to: number): PaginationPageItem[] {
  const items: PaginationPageItem[] = [];
  for (let value = from; value <= to; value++) items.push({ type: "page", value });
  return items;
}

/**
 * The truncation model (spec §5, normative — the MUI shape with `boundaryCount`
 * added). Its guaranteed property, tested exhaustively: past the threshold the
 * model's length is constant (`2b + 2s + 3`) whatever the page — the bar never
 * changes its number of cells while navigating, only what the cells hold, which
 * with `tabular-nums` is what keeps the sheet stable without a measurement.
 *
 * Private on purpose: one consumer, and the 2026-08-28 rule only applies to
 * modules that are *split out* — extracting this would cost a budget line and a
 * second gzip dictionary for nothing (the `utils/range` lesson).
 */
function getPageItems(
  page: number,
  totalPages: number,
  siblingCount: number,
  boundaryCount: number,
): PaginationPageItem[] {
  const s = Math.max(0, Math.floor(siblingCount));
  const b = Math.max(0, Math.floor(boundaryCount));

  if (totalPages <= 2 * b + 2 * s + 3) return pageRange(1, totalPages);

  const siblingsStart = Math.max(Math.min(page - s, totalPages - b - 2 * s - 1), b + 2);
  const siblingsEnd = Math.min(Math.max(page + s, b + 2 * s + 2), totalPages - b - 1);

  return [
    ...pageRange(1, b),
    siblingsStart > b + 2
      ? ({ type: "ellipsis" } as const)
      : ({ type: "page", value: b + 1 } as const),
    ...pageRange(siblingsStart, siblingsEnd),
    siblingsEnd < totalPages - b - 1
      ? ({ type: "ellipsis" } as const)
      : ({ type: "page", value: totalPages - b } as const),
    ...pageRange(totalPages - b + 1, totalPages),
  ];
}

/**
 * The one place `page` is written. Clamps to `[1, totalPages]`, returns early
 * when nothing changes — the bindable resolves controlled/uncontrolled and
 * emits `onPageChange` itself. `totalPages` can be handed in for the one caller
 * (`setPageSize`) whose ceiling is not yet readable from context: a controlled
 * `pageSize` does not move on `context.set`, and clamping the reflowed page
 * against the stale ceiling would throw away the "first visible item stays
 * visible" promise exactly when the size shrinks.
 */
function commitPage(params: Params, page: number, totalPages?: number): void {
  const { context, computed } = params;
  const total = totalPages ?? computed("totalPages");
  const clamped = Math.min(Math.max(page, 1), total);
  if (clamped === context.get("page")) return;
  context.set("page", clamped);
}

export const machine: Machine<PaginationSchema> = createMachine<PaginationSchema>({
  props({ props }) {
    return {
      count: 0,
      defaultPage: 1,
      defaultPageSize: 10,
      siblingCount: 1,
      boundaryCount: 1,
      type: "button",
      disabled: false,
      intents: null,
      ...props,
    };
  },

  context({ prop, bindable, getContext }) {
    return {
      page: bindable<number>(() => ({
        defaultValue: prop("defaultPage"),
        value: prop("page"),
        onChange: (page) =>
          prop("onPageChange")?.({ page, pageSize: getContext().get("pageSize") }),
        debugLabel: "pagination page",
      })),
      pageSize: bindable<number>(() => ({
        defaultValue: prop("defaultPageSize"),
        value: prop("pageSize"),
        onChange: (pageSize) => prop("onPageSizeChange")?.({ pageSize }),
        debugLabel: "pagination pageSize",
      })),
      focusedValue: bindable<string | null>(() => ({ defaultValue: null })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
      pressedValue: bindable<string | null>(() => ({ defaultValue: null })),
    };
  },

  computed: {
    totalPages: ({ prop, context }) =>
      Math.max(1, Math.ceil(prop("count") / Math.max(1, context.get("pageSize")))),
    page: ({ context, computed }) =>
      Math.min(Math.max(context.get("page"), 1), computed("totalPages")),
    pages: ({ prop, computed }) =>
      getPageItems(
        computed("page"),
        computed("totalPages"),
        prop("siblingCount"),
        prop("boundaryCount"),
      ),
    pageRange: ({ prop, context, computed }) => {
      const size = context.get("pageSize");
      const page = computed("page");
      return { start: (page - 1) * size, end: Math.min(page * size, prop("count")) };
    },
    canPrev: ({ prop, computed }) => !prop("disabled") && computed("page") > 1,
    canNext: ({ prop, computed }) => !prop("disabled") && computed("page") < computed("totalPages"),
  },

  initialState() {
    return "idle";
  },

  effects: ["trackModality", "captureIntents"],

  watch({ prop, context, track, action }) {
    // A page left dangling by a shrinking `count` or a changed `pageSize` is
    // re-clamped; for a controlled consumer this emits a corrective
    // `onPageChange` — the same re-settle policy as `tabs.syncTriggers`.
    track(
      () => [prop("count"), context.get("pageSize")],
      () => action(["clampPage"]),
    );
  },

  on: {
    "ITEM.CLICK": { guard: "isInteractive", actions: ["setPage"] },
    "PREV.CLICK": { guard: "canPrev", actions: ["stepPrev"] },
    "PAGE.PREV": { guard: "canPrev", actions: ["stepPrev"] },
    "NEXT.CLICK": { guard: "canNext", actions: ["stepNext"] },
    "PAGE.NEXT": { guard: "canNext", actions: ["stepNext"] },
    // Not gated, like `VALUE.SET` on tabs: the api is the consumer's own hand.
    "PAGE.SET": { actions: ["setPage"] },
    "PAGESIZE.SET": { actions: ["setPageSize"] },
    "ROOT.FOCUS": { actions: ["setFocused"] },
    "ROOT.BLUR": { actions: ["clearFocused", "clearPressed"] },
    "ROOT.PRESS_START": { guard: "isInteractive", actions: ["setPressed"] },
    "ROOT.PRESS_END": { actions: ["clearPressed"] },
    "ROOT.NAVIGATE": { guard: "isInteractive", actions: ["navigate"] },
  },

  states: {
    idle: {},
  },

  implementations: {
    guards: {
      isInteractive: ({ prop }) => !prop("disabled"),
      canPrev: ({ computed }) => computed("canPrev"),
      canNext: ({ computed }) => computed("canNext"),
    },

    actions: {
      setPage(params) {
        const { event } = params;
        if (event.type === "ITEM.CLICK" || event.type === "PAGE.SET") {
          commitPage(params, event.page);
        }
      },

      stepPrev(params) {
        commitPage(params, params.computed("page") - 1);
      },

      stepNext(params) {
        commitPage(params, params.computed("page") + 1);
      },

      /**
       * The first visible item stays visible: the new page is the one that
       * holds the old range's `start` at the new size. The size is written
       * first (it emits `onPageSizeChange`), the reflowed page second.
       */
      setPageSize(params) {
        const { prop, context, computed, event } = params;
        if (event.type !== "PAGESIZE.SET") return;
        const size = Math.max(1, Math.floor(event.size));
        if (size === context.get("pageSize")) return;
        const start = computed("pageRange").start;
        context.set("pageSize", size);
        const total = Math.max(1, Math.ceil(prop("count") / size));
        commitPage(params, Math.floor(start / size) + 1, total);
      },

      clampPage(params) {
        commitPage(params, params.computed("page"));
      },

      setFocused({ context, event, scope }) {
        if (event.type !== "ROOT.FOCUS") return;
        context.set("focusedValue", event.value);
        // Read here and held: an arrow key moving between controls is a new
        // focus, so the source follows a keyboard user across the nav, while a
        // mouse merely crossing the page never touches it.
        context.set("focusSource", getInputModality(scope.getDoc()));
      },

      clearFocused({ context }) {
        context.set("focusedValue", null);
        context.set("focusSource", null);
      },

      setPressed({ context, event }) {
        if (event.type !== "ROOT.PRESS_START") return;
        context.set("pressedValue", event.value);
      },

      clearPressed({ context }) {
        context.set("pressedValue", null);
      },

      /**
       * Moves the focus and nothing else, over the real controls in DOM order.
       * `loop: false` and not configurable: a pagination has hard ends. The
       * `aria-disabled` triggers stay targets — they are focusable by design
       * (§2), so no `isDisabled` filter is handed to the arithmetic.
       */
      navigate({ scope, event }) {
        if (event.type !== "ROOT.NAVIGATE") return;
        const controls = getControlEls(scope);
        const active = scope.getActiveElement();
        const current = active === null ? -1 : controls.indexOf(active);
        const next = getNextIndex(current, event.action, {
          count: controls.length,
          loop: false,
        });
        const target = controls[next];
        if (target === undefined || next === current) return;
        focusElement(target);
      },
    },

    effects: {
      // No listener: the source is read once, when the focus lands. Holding the
      // handle is the whole job — the tracker has to be running before the
      // first Tab.
      trackModality({ scope }) {
        return trackInputModality(scope.getDoc());
      },

      /**
       * LT/RT as `pageUp`/`pageDown`, gated on the focus being *inside* the nav
       * — unlike tabs' LB/RB, which reach in from the whole root. At a bound the
       * intent is consumed anyway (`return true` after the guard declines the
       * send): a user "in" the pagination leaning on LT must not see the page
       * scroll by surprise. Neither `trapped` nor `base`, for tabs' reasons,
       * word for word. The `preventDefault` here is what the connect's keyboard
       * guard reads to avoid playing the same step twice.
       */
      captureIntents({ prop, scope, send }) {
        const host = prop("intents");
        if (host === null || host === undefined) return;
        return host.pushScope(
          (event) => {
            if (event.intent !== "pageUp" && event.intent !== "pageDown") return false;
            if (prop("disabled") || !ownsFocus(scope)) return false;
            send({ type: event.intent === "pageDown" ? "PAGE.NEXT" : "PAGE.PREV" });
            event.preventDefault();
            return true;
          },
          { within: getRootEl(scope) },
        );
      },
    },
  },
});

import type { RovingAction } from "../../focus/roving-focus";
import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { IntentScopeHost } from "../../nav";
import type { Direction, InputModality } from "../../types";

export type PaginationItemKind = "button" | "link";

export interface PaginationPageChangeDetails {
  readonly page: number;
  readonly pageSize: number;
}

export interface PaginationPageSizeChangeDetails {
  readonly pageSize: number;
}

/** The window of visible items: `start` inclusive (0-based), `end` exclusive. */
export interface PaginationPageRange {
  readonly start: number;
  readonly end: number;
}

export type PaginationPageItem =
  | { readonly type: "page"; readonly value: number }
  | { readonly type: "ellipsis" };

export interface PaginationTranslations {
  /** Defaults to `"pagination"`. */
  readonly rootLabel?: string | undefined;
  /** Defaults to `"previous page"`. */
  readonly prevTriggerLabel?: string | undefined;
  /** Defaults to `"next page"`. */
  readonly nextTriggerLabel?: string | undefined;
  /** Defaults to `` `page ${page}` ``. */
  readonly itemLabel?: ((details: { page: number; totalPages: number }) => string) | undefined;
}

export interface PaginationItemProps {
  readonly page: number;
}

export interface PaginationEllipsisProps {
  /** Where this ellipsis sits in the page model — presentation only. */
  readonly index: number;
}

export interface PaginationMachineProps {
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  /** Total number of paginated items. Required. */
  readonly count: number;
  /** Controlled. 1-based. */
  readonly page?: number | undefined;
  readonly defaultPage?: number | undefined;
  /** Controlled. */
  readonly pageSize?: number | undefined;
  readonly defaultPageSize?: number | undefined;
  /** Pages adjacent to the current one, on each side. Default 1; 0 is allowed. */
  readonly siblingCount?: number | undefined;
  /** Pages pinned at each end. Default 1. */
  readonly boundaryCount?: number | undefined;
  /** `"button"` (default) or `"link"` — a crawlable pagination, one href per page. */
  readonly type?: PaginationItemKind | undefined;
  /** Required when `type === "link"`. */
  readonly getPageUrl?: ((details: { page: number }) => string) | undefined;
  readonly disabled?: boolean | undefined;
  readonly translations?: PaginationTranslations | undefined;
  /** Where LT/RT arrive from. `null` when the app runs no input system. */
  readonly intents?: IntentScopeHost | null | undefined;
  /**
   * Also fired *correctively*: a `count` that shrinks under the current page, or
   * a page held out of bounds by a controlled consumer, is re-clamped by the
   * machine's watch — the same re-settle policy as `tabs.syncTriggers`.
   */
  readonly onPageChange?: ((details: PaginationPageChangeDetails) => void) | undefined;
  readonly onPageSizeChange?: ((details: PaginationPageSizeChangeDetails) => void) | undefined;
}

export interface ResolvedPaginationMachineProps extends PaginationMachineProps {
  readonly count: number;
  readonly defaultPage: number;
  readonly defaultPageSize: number;
  readonly siblingCount: number;
  readonly boundaryCount: number;
  readonly type: PaginationItemKind;
  readonly disabled: boolean;
  readonly intents: IntentScopeHost | null;
}

export interface PaginationSchema extends MachineSchema {
  state: "idle";
  props: ResolvedPaginationMachineProps;
  context: {
    /** Bindable — controlled/uncontrolled resolved through `prop("page")`. */
    page: number;
    pageSize: number;
    /** `"prev"` | `"next"` | `String(page)` of the focused control, else `null`. */
    focusedValue: string | null;
    /** Read once when the focus lands, and held until it leaves (button/tabs pattern). */
    focusSource: InputModality | null;
    /** The control that is visually pressed (pointer down, or Enter/Space down). */
    pressedValue: string | null;
  };
  computed: {
    /** `max(1, ceil(count / pageSize))`. */
    totalPages: number;
    /** `clamp(context.page, 1, totalPages)` — THE readable truth. */
    page: number;
    pages: readonly PaginationPageItem[];
    pageRange: PaginationPageRange;
    canPrev: boolean;
    canNext: boolean;
  };
  event:
    | { type: "ITEM.CLICK"; page: number }
    | { type: "PREV.CLICK" }
    | { type: "NEXT.CLICK" }
    | { type: "PAGE.SET"; page: number }
    | { type: "PAGE.PREV" }
    | { type: "PAGE.NEXT" }
    | { type: "PAGESIZE.SET"; size: number }
    | { type: "ROOT.FOCUS"; value: string }
    | { type: "ROOT.BLUR" }
    | { type: "ROOT.PRESS_START"; value: string }
    | { type: "ROOT.PRESS_END" }
    | { type: "ROOT.NAVIGATE"; action: RovingAction };
  action:
    | "setPage"
    | "stepPrev"
    | "stepNext"
    | "setPageSize"
    | "clampPage"
    | "setFocused"
    | "clearFocused"
    | "setPressed"
    | "clearPressed"
    | "navigate";
  guard: "isInteractive" | "canPrev" | "canNext";
  effect: "trackModality" | "captureIntents";
}

export interface PaginationApi<T extends PropTypes = PropTypes> {
  /** Clamped — the displayable truth, whatever a controlled consumer holds. */
  readonly page: number;
  readonly pageSize: number;
  readonly totalPages: number;
  readonly pages: readonly PaginationPageItem[];
  readonly pageRange: PaginationPageRange;
  readonly isFirstPage: boolean;
  readonly isLastPage: boolean;
  setPage(page: number): void;
  setPageSize(size: number): void;
  nextPage(): void;
  prevPage(): void;
  getRootProps(): T["element"];
  /** `normalize.element` (an anchor) when `type` is `"link"`. */
  getItemProps(props: PaginationItemProps): T["button"];
  getEllipsisProps(props: PaginationEllipsisProps): T["element"];
  getPrevTriggerProps(): T["button"];
  getNextTriggerProps(): T["button"];
}

/**
 * `<Pagination count={480}/>` — and the one composed layer whose collection is
 * **not** the consumer's data.
 *
 * Every other composed component takes an array and places a part per entry.
 * Here the entries are `api.pages`, a discriminated union the machine computes
 * from `count`, `pageSize`, `siblingCount` and `boundaryCount`, and the layer
 * reads it back through `PaginationContext` — the render-prop part that exists
 * for exactly this. So there is no `options` prop and no `items` prop at all, and
 * the escape hatch is a single `renderItem` over a value the consumer never
 * supplied.
 *
 * **That is the point, and it is deliberate: this is the prototype of
 * `calendar`.** A calendar's cells are the same kind of collection — computed by
 * the machine from a month and a locale, reshaped whenever either moves, never
 * held by anybody. What this file proves for it is narrow and worth naming: a
 * machine-computed collection needs no eighth slot name (the closed vocabulary
 * of the composed layer holds), it needs one `render*` rather than one per cell
 * kind, and the key of a cell that carries no identity of its own comes from its
 * *position* — never from a neighbour that has one, because the neighbours are
 * exactly what a page turn changes. What it does **not** prove is the part a
 * calendar adds on top — a grid with two axes, a roving focus that moves in two
 * directions, and a collection that changes under the focus rather than beside
 * it.
 *
 * Zero glyph bytes here: `prev` and `next` carry `"previous page"` and
 * `"next page"` from the machine's own translations, and the ellipsis is already
 * drawn by `_pagination.scss` under `:empty`. The two label slots are visible
 * content, not names — a consumer who hands in a chevron gets the chevron and
 * keeps the name the machine wrote.
 */

import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import {
  PaginationContext,
  PaginationEllipsis,
  type PaginationEllipsisProps,
  PaginationItem,
  type PaginationItemProps,
  PaginationNextTrigger,
  PaginationPrevTrigger,
  PaginationRoot,
  type UsePaginationProps,
} from "./pagination";

/**
 * The escape hatch, applied **last** on every part: what the layer defaults is a
 * default, and the consumer's entry wins over it.
 *
 * Four keys for the five parts of `pagination.anatomy.ts`. The fifth, `root`, is
 * absent because it is not reachable through a hatch here — this component *has*
 * a root element, so its props are the composed props themselves, `render`
 * included.
 */
export interface PaginationParts {
  /**
   * Applied to EVERY cell, hence no `page` — it identifies the cell — and no `id`
   * **or IDREF**: one id repeated down a bar is a broken reference per cell, and
   * one `aria-labelledby` repeated gives every cell the same name, which no
   * dangling-IDREF check can see because the id it points at does resolve. `ref`
   * goes for the same reason: a single ref held by N cells holds the last one.
   */
  readonly item?:
    | Omit<
        PaginationItemProps,
        "page" | "id" | "ref" | "aria-labelledby" | "aria-describedby" | "aria-controls"
      >
    | undefined;
  /** Applied to EVERY gap; `index` is the machine's, one per gap. */
  readonly ellipsis?:
    | Omit<
        PaginationEllipsisProps,
        "index" | "id" | "ref" | "aria-labelledby" | "aria-describedby" | "aria-controls"
      >
    | undefined;
  readonly prevTrigger?: PartProps<"button"> | undefined;
  readonly nextTrigger?: PartProps<"button"> | undefined;
}

export interface PaginationComposedProps
  extends UsePaginationProps,
    Omit<PartProps<"nav", UsePaginationProps>, "children"> {
  /**
   * What the previous-page control shows. Content, never its name: the machine
   * writes `aria-label="previous page"` whatever is in here, so an inline SVG
   * costs nothing and an empty control is a drawn one rather than a blank.
   */
  readonly prevLabel?: ReactNode;
  /** The same, for the next-page control. */
  readonly nextLabel?: ReactNode;
  /**
   * Replaces the CHILDREN of a page cell, never the cell. `defaults` is what the
   * layer would have rendered — the page number — and it is handed over so that
   * **decorating** is the cheapest thing to do. Replacing it is the consumer's to
   * do and costs nothing this time: the cell's accessible name is `aria-label` on
   * the button, written by the machine, so a cell whose children are a spinner is
   * still "page 4". That is a difference from every other `render*` in the
   * composed layer, and it is worth stating rather than assuming.
   */
  readonly renderItem?: ((page: number, defaults: ReactNode) => ReactNode) | undefined;
  readonly parts?: PaginationParts | undefined;
}

export function Pagination(props: PaginationComposedProps): ReactNode {
  const { prevLabel, nextLabel, renderItem, parts, ...root } = props;

  return (
    <PaginationRoot {...root}>
      <PaginationPrevTrigger {...parts?.prevTrigger}>{prevLabel}</PaginationPrevTrigger>
      <PaginationContext>
        {(api) =>
          api.pages.map((entry, index) => {
            if (entry.type === "ellipsis") {
              // A gap has no identity of its own, and the pages around it are the
              // wrong place to borrow one from: they change on every page turn, so
              // a key made of them unmounts and remounts both ellipses each time.
              // There are exactly two gaps and they are *positions* — one before
              // the window, one after — so that is the key.
              //
              // Ratified 2026-09-05, and this module is why it had to be: three
              // conventions were live in the repo at once (`gap-after-<page>` in
              // `ssr.test.tsx`, `gap-start`/`gap-end` in the story, `gap-<a>-<b>`
              // in the browser test) and the composed layer picks one for every
              // consumer. The story's was the only one backed by a measurement.
              return (
                <PaginationEllipsis
                  key={index < api.pages.length / 2 ? "gap-start" : "gap-end"}
                  index={index}
                  {...parts?.ellipsis}
                />
              );
            }
            return (
              <PaginationItem key={entry.value} page={entry.value} {...parts?.item}>
                {renderItem === undefined ? entry.value : renderItem(entry.value, entry.value)}
              </PaginationItem>
            );
          })
        }
      </PaginationContext>
      <PaginationNextTrigger {...parts?.nextTrigger}>{nextLabel}</PaginationNextTrigger>
    </PaginationRoot>
  );
}

export type {
  PaginationItemKind,
  PaginationMachineProps,
  PaginationPageChangeDetails,
  PaginationPageItem,
  PaginationPageRange,
  PaginationPageSizeChangeDetails,
  PaginationTranslations,
} from "@standarui/core/pagination";
export {
  Pagination,
  type PaginationComposedProps,
  type PaginationParts,
} from "./composed";
export {
  type PaginationApi,
  PaginationContext,
  type PaginationContextProps,
  PaginationEllipsis,
  type PaginationEllipsisProps,
  PaginationItem,
  type PaginationItemProps,
  PaginationNextTrigger,
  PaginationPrevTrigger,
  PaginationRoot,
  type PaginationRootProps,
  type UsePaginationProps,
  usePagination,
  usePaginationContext,
} from "./pagination";

/**
 * Pagination in React: one machine in the root, five thin parts, and a
 * render-prop context so a consumer can map `api.pages` without reaching for
 * the hook.
 *
 * The one decision the adapter owns is the element: `type="link"` renders every
 * control as an anchor, `"button"` (the default) as a button. That flag rides
 * the part context rather than being re-read from the api — `connect` already
 * spent it on the props, only the tag choice is left, and the tag is React's.
 *
 * The intent scope LT/RT arrive on is taken from the nearest
 * `<NavProvider>`, exactly as `tabs` wires LB/RB.
 */

import type { Service } from "@standarui/core";
import * as pagination from "@standarui/core/pagination";
import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import { useIntentScopeHost } from "../../nav";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type PaginationApi = pagination.PaginationApi<ReactPropTypes>;

export interface UsePaginationProps
  extends pagination.PaginationMachineProps,
    MachineRuntimeProps {}

interface PaginationContextValue {
  readonly api: PaginationApi;
  /** Mirrored off the machine props: the parts pick their element from it. */
  readonly link: boolean;
}

const PaginationPartContext = createPartContext<PaginationContextValue>("Pagination");

function usePaginationService(props: UsePaginationProps): Service<pagination.PaginationSchema> {
  const host = useIntentScopeHost();

  return useMachine(pagination.machine, {
    ...props,
    // `??` would override an explicit `null`, and `null` is how a consumer says
    // "this pagination answers no gamepad" while a provider is mounted above.
    intents: props.intents === undefined ? host : props.intents,
  });
}

export function usePagination(props: UsePaginationProps): PaginationApi {
  return pagination.connect(usePaginationService(props), normalizeProps);
}

/** The api of the pagination a subtree sits in — a consumer's own chrome reads it. */
export function usePaginationContext(): PaginationApi {
  return PaginationPartContext.usePart("PaginationContext").api;
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "count",
  "page",
  "defaultPage",
  "pageSize",
  "defaultPageSize",
  "siblingCount",
  "boundaryCount",
  "type",
  "getPageUrl",
  "disabled",
  "translations",
  "intents",
  "onPageChange",
  "onPageSizeChange",
] as const;

export interface PaginationRootProps
  extends UsePaginationProps,
    PartProps<"nav", UsePaginationProps> {}

export function PaginationRoot(props: PaginationRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const api = usePagination(machineProps);

  const context: PaginationContextValue = { api, link: machineProps.type === "link" };

  return (
    <PaginationPartContext.Provider value={context}>
      {useRender({
        render,
        asChild,
        element: "nav",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </PaginationPartContext.Provider>
  );
}

export interface PaginationItemProps
  extends pagination.PaginationItemProps,
    PartProps<"button", pagination.PaginationItemProps> {}

/**
 * An item is identified by its page and nothing else: its neighbours and the
 * focus order are read back off the DOM by the machine, so a cell rendered
 * conditionally — which is every cell, since `api.pages` reshapes as the window
 * slides — never goes out of sync with a registry.
 */
export function PaginationItem(props: PaginationItemProps): ReactNode {
  const [itemProps, rest] = splitProps(props, ["page"]);
  const { render, asChild, children, ...elementProps } = rest;
  const { api, link } = PaginationPartContext.usePart("PaginationItem");

  return useRender({
    render,
    asChild,
    element: link ? "a" : "button",
    props: api.getItemProps(itemProps),
    elementProps,
    children,
  });
}

export interface PaginationEllipsisProps
  extends pagination.PaginationEllipsisProps,
    PartProps<"span", pagination.PaginationEllipsisProps> {}

/**
 * Purely presentational, `aria-hidden`. The content is the consumer's — an
 * inline SVG, never the `…` glyph, whose ink sits on its baseline rather than
 * in the middle of its box.
 */
export function PaginationEllipsis(props: PaginationEllipsisProps): ReactNode {
  const [ellipsisProps, rest] = splitProps(props, ["index"]);
  const { render, asChild, children, ...elementProps } = rest;
  const { api } = PaginationPartContext.usePart("PaginationEllipsis");

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getEllipsisProps(ellipsisProps),
    elementProps,
    children,
  });
}

export function PaginationPrevTrigger(props: PartProps<"button">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const { api, link } = PaginationPartContext.usePart("PaginationPrevTrigger");

  return useRender({
    render,
    asChild,
    element: link ? "a" : "button",
    props: api.getPrevTriggerProps(),
    elementProps,
    children,
  });
}

export function PaginationNextTrigger(props: PartProps<"button">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const { api, link } = PaginationPartContext.usePart("PaginationNextTrigger");

  return useRender({
    render,
    asChild,
    element: link ? "a" : "button",
    props: api.getNextTriggerProps(),
    elementProps,
    children,
  });
}

export interface PaginationContextProps {
  /** Handed the connected api — the way a consumer maps `api.pages` into cells. */
  readonly children: (api: PaginationApi) => ReactNode;
}

export function PaginationContext(props: PaginationContextProps): ReactNode {
  return props.children(usePaginationContext());
}
